	var daisy_shim_default = "/* The skin gets these from daisyUI; the plugin does not take that dependency for\n   14 classes (PORT_PLAN §4 spirit — see also base-100/200/300 in skin-vars.css).\n   This implements exactly the daisyUI surface the ported settings markup uses.\n   Sized for the 1920x1200 design reference, not daisyUI's web defaults.\n\n   If a category starts using a new daisyUI class, add it here; `npm run\n   audit:daisy` lists what the ported markup references. */\n\n/* ── .btn ─────────────────────────────────────────────────────────────────── */\n.btn {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    gap: 8px;\n    height: 60px;\n    padding: 0 28px;\n    border-radius: 10px;\n    font-size: 22px;\n    font-weight: 600;\n    line-height: 1;\n    text-align: center;\n    background-color: var(--button-grey);\n    color: var(--text-primary);\n    border: 1px solid transparent;\n    cursor: pointer;\n    transition: background-color .15s, opacity .15s;\n}\n.btn:hover { opacity: .85; }\n.btn:disabled { opacity: .5; cursor: default; }\n.btn-primary { background-color: var(--mimoja-blue); color: #fff; }\n.btn-error { background-color: var(--status-red-color); color: #fff; }\n.btn-sm { height: 44px; padding: 0 18px; font-size: 19px; }\n\n/* ── .checkbox ────────────────────────────────────────────────────────────── */\n.checkbox {\n    appearance: none;\n    -webkit-appearance: none;\n    flex-shrink: 0;\n    width: 30px;\n    height: 30px;\n    border: 2px solid var(--toggle-off-border);\n    border-radius: 6px;\n    background-color: var(--profile-button-background-color);\n    cursor: pointer;\n    display: inline-grid;\n    place-content: center;\n}\n.checkbox:checked::before {\n    content: \"\";\n    width: 16px;\n    height: 16px;\n    /* Inset box-shadow, not a background: survives the appearance:none reset. */\n    box-shadow: inset 16px 16px currentColor;\n    clip-path: polygon(14% 44%, 0 65%, 50% 100%, 100% 16%, 80% 0%, 43% 62%);\n}\n.checkbox-primary:checked { border-color: var(--mimoja-blue); color: var(--mimoja-blue); }\n.checkbox:disabled { opacity: .5; cursor: default; }\n\n/* ── .input ───────────────────────────────────────────────────────────────── */\n.input {\n    height: 60px;\n    padding: 0 16px;\n    border-radius: 8px;\n    font-size: 22px;\n    line-height: 1;\n    background-color: var(--profile-button-background-color);\n    color: var(--text-primary);\n    border: 1px solid transparent;\n}\n.input-bordered { border-color: var(--border-color); }\n.input:focus { outline: none; border-color: var(--mimoja-blue); }\n\n/* ── .modal ───────────────────────────────────────────────────────────────── */\n/* Applied to <dialog>, which showModal() already centres and backdrops; these\n   only supply the panel's own box. */\n.modal {\n    border: 0;\n    padding: 0;\n    background: transparent;\n    max-width: none;\n    max-height: none;\n}\n.modal::backdrop { background: rgba(0, 0, 0, .45); }\n.modal-box {\n    padding: 36px 40px;\n    border-radius: 20px;\n    background-color: var(--box-color);\n    color: var(--text-primary);\n    max-height: 80vh;\n    overflow-y: auto;\n}\n.modal-action {\n    display: flex;\n    justify-content: flex-end;\n    gap: 14px;\n    margin-top: 26px;\n}\n\n/* ── .loading ─────────────────────────────────────────────────────────────── */\n.loading {\n    display: inline-block;\n    aspect-ratio: 1 / 1;\n    width: 28px;\n    border: 3px solid currentColor;\n    border-right-color: transparent;\n    border-radius: 50%;\n    animation: daisy-spin .7s linear infinite;\n    /* daisyUI's spinner is a mask; a border ring reads identically at these sizes. */\n    color: var(--mimoja-blue);\n}\n.loading-lg { width: 44px; border-width: 4px; }\n@keyframes daisy-spin { to { transform: rotate(360deg); } }\n";
